import XCTest
@testable import MyCoach

/// The Swift planner must match the TypeScript reference (web/src/engines/mealPlanner.ts) exactly.
/// `MealPlannerFixture` is generated by `GEN_FIXTURE=1 npm run fixtures` in web/.
final class MealPlannerTests: XCTestCase {
    private struct Fixture: Decodable { var cases: [Case] }

    private struct Case: Decodable {
        var name: String
        var weekday: Int
        var isTrainingDay: Bool
        var target: Target
        var ctx: Context
        var swapItem: SwapItem?
        var swapMeal: Int?
        var expected: Summary
        var expectedAfterSwaps: Summary?
    }

    private struct Target: Decodable {
        var calories: Int
        var protein: Double
        var carbs: Double
        var fat: Double
    }

    private struct Context: Decodable {
        var allergies: [String]
        var dislikedFoods: [String]
        var preferredFoods: [String]
        var trainingTime: String
        var intraWorkoutEnabled: Bool
        var weightKg: Double
        var goal: String
    }

    private struct SwapItem: Decodable {
        var meal: Int
        var item: Int
        var foodKey: String
    }

    private struct Summary: Decodable {
        var meals: [MealSummary]
        var ok: Bool
        var protein: Double
        var carbs: Double
        var fat: Double
        var kcal: Double
    }

    private struct MealSummary: Decodable {
        var slot: String
        var recipeId: String?
        var items: [ItemSummary]
    }

    private struct ItemSummary: Decodable {
        var id: String
        var amount: Double
        var locked: Bool
    }

    private func loadFixture() throws -> Fixture {
        try JSONDecoder().decode(Fixture.self, from: Data(MealPlannerFixture.json.utf8))
    }

    private func context(_ c: Context) throws -> PlannerContext {
        PlannerContext(
            allergies: try c.allergies.map { try XCTUnwrap(FoodAllergy(rawValue: $0)) },
            dislikedFoods: c.dislikedFoods,
            preferredFoods: c.preferredFoods,
            trainingTime: try XCTUnwrap(TrainingTimePreference(rawValue: c.trainingTime)),
            intraWorkoutEnabled: c.intraWorkoutEnabled,
            weightKg: c.weightKg,
            goal: try XCTUnwrap(GoalPhase(rawValue: c.goal))
        )
    }

    private func assertMatches(_ plan: MealPlanDay, _ expected: Summary, _ tag: String) {
        XCTAssertEqual(plan.meals.count, expected.meals.count, "\(tag) meal count")
        for (m, (meal, exp)) in zip(plan.meals, expected.meals).enumerated() {
            XCTAssertEqual(meal.slot.rawValue, exp.slot, "\(tag) meal \(m) slot")
            XCTAssertEqual(meal.recipeID, exp.recipeId, "\(tag) meal \(m) recipe")
            XCTAssertEqual(meal.items.count, exp.items.count, "\(tag) meal \(m) item count")
            for (i, (item, e)) in zip(meal.items, exp.items).enumerated() {
                XCTAssertEqual(item.food.id.uuidString.lowercased(), e.id.lowercased(), "\(tag) meal \(m) item \(i) food")
                XCTAssertEqual(item.grams ?? item.servings ?? -1, e.amount, accuracy: 1e-9, "\(tag) meal \(m) item \(i) amount")
                XCTAssertEqual(item.isLocked, e.locked, "\(tag) meal \(m) item \(i) lock")
            }
        }
        let v = MealPlanner.validate(plan)
        XCTAssertEqual(v.ok, expected.ok, "\(tag) ok")
        XCTAssertEqual(v.protein, expected.protein, accuracy: 1e-6, "\(tag) protein")
        XCTAssertEqual(v.carbs, expected.carbs, accuracy: 1e-6, "\(tag) carbs")
        XCTAssertEqual(v.fat, expected.fat, accuracy: 1e-6, "\(tag) fat")
        XCTAssertEqual(v.kcal, expected.kcal, accuracy: 1e-6, "\(tag) kcal")
    }

    // MARK: - Cross-platform parity

    func testMatchesTypeScriptReferenceIncludingSwaps() throws {
        let fixture = try loadFixture()
        XCTAssertFalse(fixture.cases.isEmpty)
        for c in fixture.cases {
            let ctx = try context(c.ctx)
            let target = DailyNutritionTarget(
                calories: c.target.calories,
                macros: MacroGrams(protein: c.target.protein, carbohydrates: c.target.carbs, fat: c.target.fat),
                isTrainingDay: c.isTrainingDay,
                stepTarget: 8000
            )
            let plan = MealPlanner.generateDay(
                date: Date(),
                weekday: try XCTUnwrap(Weekday(rawValue: c.weekday)),
                isTrainingDay: c.isTrainingDay,
                target: target,
                context: ctx
            )
            assertMatches(plan, c.expected, c.name)

            guard let afterExpected = c.expectedAfterSwaps else { continue }
            var after = plan
            if let s = c.swapItem {
                let item = after.meals[s.meal].items[s.item]
                let food = MealPlanner.foodItem(try XCTUnwrap(MealPlanner.plannerFood(key: s.foodKey)))
                after = MealPlanner.swapItem(after, itemID: item.id, with: food).plan
            }
            if let m = c.swapMeal {
                after = MealPlanner.swapMeal(after, mealID: after.meals[m].id, context: ctx)
            }
            assertMatches(after, afterExpected, "\(c.name) after swaps")
        }
    }

    // MARK: - Rules

    private func plan(weightKg: Double, goal: GoalPhase, training: Bool, allergies: [FoodAllergy] = []) -> MealPlanDay {
        let engine = NutritionEngine()
        let pair = engine.buildInitialTargets(
            for: NutritionEngine.ProfileInput(
                weightKg: weightKg,
                heightCm: 178,
                ageYears: 30,
                sex: .male,
                goal: goal,
                activityBand: .sixToEight,
                trainingDaysPerWeek: 4,
                stepTarget: 8000,
                intraWorkoutEnabled: true
            )
        )
        return MealPlanner.generateDay(
            date: Date(),
            weekday: .wednesday,
            isTrainingDay: training,
            target: pair.target(isTrainingDay: training),
            context: PlannerContext(
                allergies: allergies,
                dislikedFoods: [],
                preferredFoods: [],
                trainingTime: .evening,
                intraWorkoutEnabled: true,
                weightKg: weightKg,
                goal: goal
            )
        )
    }

    func testProteinIsOneGramPerPound() {
        let engine = NutritionEngine()
        XCTAssertEqual(engine.proteinGrams(weightKg: 80, goal: .cut), 176.37, accuracy: 0.01)
        XCTAssertEqual(engine.proteinGrams(weightKg: 80, goal: .gain), 176.37, accuracy: 0.01)
    }

    func testPlansAreValidPracticalAndWeighedRaw() {
        for weight in [60.0, 80.0, 100.0] {
            for goal in [GoalPhase.cut, .gain] {
                for training in [true, false] {
                    let day = plan(weightKg: weight, goal: goal, training: training)
                    let v = MealPlanner.validate(day)
                    XCTAssertTrue(v.ok, "\(weight) \(goal) \(training): \(v.issues)")
                    XCTAssertGreaterThanOrEqual(v.protein, day.target.macros.protein - PlannerConfig.proteinUnderToleranceG)
                    for meal in day.meals {
                        let sources = Set(
                            meal.items.map { MealPlanner.spec(for: $0.food) }
                                .filter { $0.role == .protein }
                                .map { $0.group ?? $0.key }
                        )
                        XCTAssertEqual(sources.count, 1, "\(meal.name) must have exactly one main protein source")
                        for item in meal.items {
                            XCTAssertNotEqual(item.food.measurementState, .cooked, "\(item.food.name) must be weighed raw/dry")
                            let spec = MealPlanner.spec(for: item.food)
                            if spec.role != .supplement {
                                XCTAssertTrue(MealPlanner.domain(of: spec).contains(item.grams ?? item.servings ?? -1))
                            }
                        }
                    }
                }
            }
        }
    }

    func testSwappingToCookedFoodUsesRawEntry() throws {
        let day = plan(weightKg: 80, goal: .cut, training: true)
        let chicken = try XCTUnwrap(day.meals.flatMap(\.items).first { $0.food.name == "Chicken Breast" })
        let cookedBeef = FoodItem(
            name: "Lean Beef (5% fat)",
            source: .bundledGeneric,
            servingDescription: "100 g cooked",
            servingGrams: 100,
            calories: 176,
            proteinGrams: 26,
            carbohydrateGrams: 0,
            fatGrams: 8,
            measurementState: .cooked
        )
        let swapped = MealPlanner.swapItem(day, itemID: chicken.id, with: cookedBeef).plan
        let item = try XCTUnwrap(swapped.meals.flatMap(\.items).first { $0.id == chicken.id })
        XCTAssertEqual(item.food.measurementState, .raw)
        XCTAssertTrue(MealPlanner.validate(swapped).ok)
        XCTAssertTrue(swapped.solverMessage?.contains("raw") ?? false)
    }

    func testPlannerFoodsMatchFourFourNine() {
        for food in MealPlanner.foods {
            XCTAssertNotEqual(food.state, .cooked)
            XCTAssertTrue(MealPlanner.databaseKcalConsistent(food), food.name)
        }
    }
}
